input.command:
export IMPLEMENT_TMPDIR=<TMPDIR>
export CLAUDE_PLUGIN_ROOT=<OPERATOR_REPO_PATH>/plugins/cache/larch-local/larch/42.5.23
LARCH_TOKEN_SESSION_ID=$("$CLAUDE_PLUGIN_ROOT/scripts/read-session-env-key.sh" --file "$IMPLEMENT_TMPDIR/session-env.sh" --key LARCH_TOKEN_SESSION_ID --default "")
LARCH_CLAUDE_SOURCE_FILE=$("$CLAUDE_PLUGIN_ROOT/scripts/read-session-env-key.sh" --file "$IMPLEMENT_TMPDIR/session-env.sh" --key LARCH_CLAUDE_SOURCE_FILE --default "")
LARCH_TIMING_LEDGER=$("$CLAUDE_PLUGIN_ROOT/scripts/read-session-env-key.sh" --file "$IMPLEMENT_TMPDIR/session-env.sh" --key LARCH_TIMING_LEDGER --default "")
export LARCH_TOKEN_SESSION_ID LARCH_CLAUDE_SOURCE_FILE LARCH_TIMING_LEDGER

_launch_id="run-step2-dispatch.1315"
export LARCH_BREADCRUMB_STREAM="$IMPLEMENT_TMPDIR/breadcrumbs/run-step2-dispatch.${_launch_id}.ndjson"
export LARCH_DONE_SENTINEL=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.done.* 2>/dev/null | head -1)
export LARCH_STATUS_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.status.* 2>/dev/null | head -1)
export LARCH_QUIET_LOG_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.quiet.* 2>/dev/null | head -1)
export LARCH_BREADCRUMBS_SURFACED_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.surfaced.* 2>/dev/null | head -1)
export LARCH_PAIRED_PID_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.${_launch_id}.pid.* 2>/dev/null | head -1)
echo "sentinel=$LARCH_DONE_SENTINEL"

export IMPLEMENT_TMPDIR=<TMPDIR>
export CLAUDE_PLUGIN_ROOT=<OPERATOR_REPO_PATH>/plugins/cache/larch-local/larch/42.5.23

_launch_id="run-step5-review.32061"
export LARCH_BREADCRUMB_STREAM="$IMPLEMENT_TMPDIR/breadcrumbs/run-step5-review.${_launch_id}.ndjson"
export LARCH_DONE_SENTINEL=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step5-review.${_launch_id}.done.* | head -1)
export LARCH_STATUS_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step5-review.${_launch_id}.status.* | head -1)
export LARCH_QUIET_LOG_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step5-review.${_launch_id}.quiet.* | head -1)
export LARCH_BREADCRUMBS_SURFACED_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step5-review.${_launch_id}.surfaced.* | head -1)
export LARCH_PAIRED_PID_FILE=$(ls "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step5-review.${_launch_id}.pid.* | head -1)

"$CLAUDE_PLUGIN_ROOT/scripts/breadcrumb-monitor.sh" \
  --stream "$LARCH_BREADCRUMB_STREAM" \
  --done-sentinel "$LARCH_DONE_SENTINEL" \
  --status-file "$LARCH_STATUS_FILE" \
  --quiet-log "$LARCH_QUIET_LOG_FILE" \
  --surfaced-sentinel "$LARCH_BREADCRUMBS_SURFACED_FILE" \
  --paired-pid-file "$LARCH_PAIRED_PID_FILE"
